// v0.4 finite timeline tests use a controlled clock, RAF and Canvas doubles.
// They establish UI/controller ordering, not real scheduling or rendered pixels.
const Q=require('./sequence-fixtures.cjs');
async function importSequence(h,value=Q.sequence()){const text=JSON.stringify(value);h.get('sequence-import').files=[{name:'synthetic-sequence.json',size:Buffer.byteLength(text),text:async()=>text}];await h.fire('sequence-import','change');}
async function exportSequence(h){const before=h.downloads.length;await h.fire('sequence-export','click');return h.downloads.length===before?null:JSON.parse(await h.downloads.at(-1).blob.text());}
async function startSequence(h,value=Q.sequence()){await importSequence(h,value);h.advance();await h.fire('sequence-play','click');assert.equal(h.visible(),true);assert.equal(h.get('sequence-pause').hidden,false);assert.equal(h.rafPending.size,1);}
const blends=h=>h.paint.filter(p=>p.method==='drawImage');

