 clearDraws(h);h.runFrame(1);assertOnlyBlackPaint(h);assert.equal(h.rafPending.size,0);assert.equal(h.get('sequence-progress').textContent,'Stopped');assert.match(h.status(),/finished|reset/i);h.advance(100000);h.runFrame(100000);assert.equal(h.visible(),false);assert.equal(h.maxRafPending,1);
