for(const reason of ['background','empty','geometry','capacity','total'])test(`UI DOUBLE V4 ATOMIC: ${reason} capture rejection preserves accepted scene, history and sequence`,async()=>{
 const h=createHarness();await h.input('scene-name','Accepted A');await h.submit();await h.input('scene-name','Accepted B');await h.submit();const priorScene=await h.exportScene(),q=Q.sequence({background:priorScene.scene.background});
 if(reason==='capacity')q.sequence.steps=Array.from({length:32},(_,i)=>({...Q.clone(q.sequence.steps[0]),id:'step-'+i,transitionMs:i===31?0:1000}));if(reason==='total')q.sequence.steps=Array.from({length:6},(_,i)=>({...Q.clone(q.sequence.steps[0]),id:'step-'+i,holdMs:600000,transitionMs:0}));await importSequence(h,q);const priorSequence=await exportSequence(h);await h.input('scene-name','Unaccepted capture');if(reason==='background')await h.input('background-lightness',10);if(reason==='geometry')await h.input('position-x',0);if(reason==='empty')for(let i=0;i<3;i++)await h.fire('delete-object','click');await h.fire('capture-add','click');assert.equal(h.visible(),false);assert.match(h.status(),/Neither accepted document|unchanged|32/i);assert.deepEqual(await exportSequence(h),priorSequence);await h.fire('discard','click');assert.deepEqual(await h.exportScene(),priorScene);await h.fire('undo','click');assert.equal((await h.exportScene()).scene.name,'Accepted A');
});
test('UI DOUBLE V4: reorder normalizes final transitions, preserves others, and rejects over-total moves atomically',async()=>{
 const h=createHarness(),q=Q.sequence();q.sequence.steps[0].transitionMs=2500;await importSequence(h,q);await h.select('sequence-step-select','2');await h.fire('sequence-move-up','click');const moved=await exportSequence(h);assert.deepEqual(moved.sequence.steps.map(s=>s.id),['step-1','step-3','step-2']);assert.deepEqual(moved.sequence.steps.map(s=>s.transitionMs),[2500,1000,0]);const full=Q.sequence({steps:Array.from({length:6},(_,i)=>({...Q.clone(Q.sequence().sequence.steps[0]),id:'step-'+i,holdMs:600000,transitionMs:0}))});await importSequence(h,full);await h.select('sequence-step-select','5');await h.fire('sequence-move-up','click');assert.deepEqual(await exportSequence(h),full);assert.equal(h.visible(),false);
});
test('UI DOUBLE V4: loading a step blocks unresolved static edits, then copies without linking documents',async()=>{
 const h=createHarness();await importSequence(h);await h.input('scene-name','Unresolved scene');await h.fire('sequence-load','click');assert.match(h.status(),/Apply or discard/i);assert.equal(h.get('scene-name').value,'Unresolved scene');await h.fire('discard','click');await h.fire('sequence-load','click');assert.equal(h.get('scene-name').value,'Circle');assert.equal(h.get('scene-panel').hidden,false);await h.input('object-hue',20);await h.submit();assert.deepEqual(await exportSequence(h),Q.sequence());
});
test('UI DOUBLE V4: sequence-mode skip exposes scene controls before focusing; no hidden decorative circle remains',async()=>{
 const h=createHarness();await h.fire('workspace-sequence','click');await h.fire('skip-controls','click');assert.equal(h.get('scene-panel').hidden,false);assert.equal(h.document.activeElement.id,'controls');const fs=require('node:fs');assert.doesNotMatch(fs.readFileSync(require.resolve('../src/shell.html'),'utf8'),/class="quiet-mark"/);
});
for(const action of ['play','stop','edit','scene-import','newer-sequence','fullscreen'])test(`UI DOUBLE V4 RACE: delayed sequence file cannot replace state after ${action}`,async()=>{
 const h=createHarness();await importSequence(h);let resolve;h.get('sequence-import').files=[{size:100,text:()=>new Promise(r=>resolve=r)}];const pending=h.fire('sequence-import','change');if(action==='play'){h.advance();await h.fire('sequence-play','click')}else if(action==='stop')await h.fire('sequence-stop','click');else if(action==='edit')await h.input('sequence-name','New accepted title');else if(action==='scene-import')await h.import(JSON.stringify(scene()));else if(action==='newer-sequence')await importSequence(h,Q.shortSequence());else await h.fire('fullscreen','click');const name=h.get('sequence-name').value,count=h.get('sequence-count').textContent;resolve(JSON.stringify(Q.sequence({name:'STALE'})));await pending;assert.equal(h.get('sequence-name').value,name);assert.equal(h.get('sequence-count').textContent,count);await h.fire('sequence-stop','click');assert.equal(h.visible(),false);
});
for(const paused of [false,true])test(`UI DOUBLE V4 REGRESSION: ${paused?'paused':'running'} timeline cannot cross to manual Show without concealment and fresh guard`,async()=>{
 const h=createHarness();await startSequence(h);h.runFrame(3500);if(paused)await h.fire('sequence-pause','click');const stale=paused?h.cancelledFrames.at(-1).fn:[...h.rafPending.values()][0];assert.equal(h.get('sequence-show').disabled,true);clearDraws(h);await h.fire('sequence-show','click');assertOnlyBlackPaint(h);assert.equal(h.rafPending.size,0);await h.fire('sequence-resume','click');assert.equal(h.visible(),false);await h.fire('sequence-show','click');assert.equal(h.visible(),false);clearDraws(h);stale(999999);assert.equal(h.paint.length,0);h.advance();await h.fire('sequence-show','click');assert.equal(h.visible(),true);assert.equal(h.rafPending.size,0);
});
test('UI DOUBLE V4 REGRESSION: visible manual step cannot switch to Play or static Show through already-visible fastpath',async()=>{
 const h=createHarness();await importSequence(h);h.advance();await h.fire('sequence-show','click');assert.equal(h.visible(),true);clearDraws(h);await h.fire('sequence-play','click');assertOnlyBlackPaint(h);assert.equal(h.rafPending.size,0);await h.fire('sequence-play','click');assert.equal(h.visible(),false);h.advance();await h.fire('sequence-play','click');assert.equal(h.visible(),true);clearDraws(h);await h.fire('show-scene','click');assertOnlyBlackPaint(h);await h.fire('show-scene','click');assert.equal(h.visible(),false);h.advance();await h.fire('show-scene','click');assert.equal(h.visible(),true);assert.equal(h.rafPending.size,0);
});
for(const failure of ['nonfinite','throws'])test(`UI DOUBLE V4: ${failure} playback clock conceals and latches future reveal closed`,async()=>{
 const h=createHarness();await startSequence(h);h.runFrame(3500);h.sandbox.performance.now=()=>{if(failure==='throws')throw Error('Synthetic clock failure');return NaN};clearDraws(h);h.runFrame(16);assertOnlyBlackPaint(h);assert.equal(h.rafPending.size,0);h.sandbox.performance.now=()=>1000000;await h.fire('sequence-play','click');assert.equal(h.visible(),false);await h.fire('show-scene','click');assert.equal(h.visible(),false);await h.fire('sequence-show','click');assert.equal(h.visible(),false);assert.equal(h.rafPending.size,0);
});

for(const failure of ['nonfinite','throws'])test(`UI DOUBLE V4 REGRESSION: one-shot ${failure} gate clock fault hides before subsequent valid engine tick`,async()=>{
 const h=createHarness();await startSequence(h);h.runFrame(3500);const original=h.sandbox.performance.now;let calls=0;h.sandbox.performance.now=()=>{if(++calls===1){if(failure==='throws')throw Error('Synthetic one-shot clock failure');return NaN}return original()};clearDraws(h);h.runFrame(16);assertOnlyBlackPaint(h);assert.equal(h.rafPending.size,0);assert.ok(calls>=1);h.sandbox.performance.now=original;h.advance(100000);await h.fire('sequence-play','click');assert.equal(h.visible(),false);await h.fire('show-scene','click');assert.equal(h.visible(),false);await h.fire('sequence-show','click');assert.equal(h.visible(),false);assert.equal(h.rafPending.size,0);
});
test('UI DOUBLE V4: completion and Escape recover playback focus to persistent Stop',async()=>{
 const h=createHarness();await startSequence(h);h.get('sequence-pause').focus();h.runFrame(11000);assert.equal(h.visible(),false);assert.equal(h.document.activeElement.id,'sequence-stop');h.advance();await h.fire('sequence-play','click');h.runFrame(3500);await h.fire('sequence-pause','click');h.get('sequence-resume').focus();await h.globalEvent('document','keydown',{key:'Escape'});assert.equal(h.visible(),false);assert.equal(h.document.activeElement.id,'sequence-stop');assert.equal(h.rafPending.size,0);
});

test('UI DOUBLE V4 REGRESSION: native-like synchronous auto-blur on hidden or disabled playback controls still recovers Stop focus',async()=>{
 const h=createHarness();for(const id of ['sequence-play','sequence-pause','sequence-resume','sequence-show'])for(const prop of ['hidden','disabled']){const el=h.get(id);let value=el[prop];Object.defineProperty(el,prop,{get:()=>value,set(next){value=next;if(next&&h.document.activeElement===el)h.document.activeElement=h.document.body}})}
 await startSequence(h);h.get('sequence-pause').focus();h.runFrame(11000);assert.equal(h.visible(),false);assert.equal(h.document.activeElement.id,'sequence-stop');h.advance();await h.fire('sequence-play','click');h.runFrame(3500);await h.fire('sequence-pause','click');h.get('sequence-resume').focus();await h.globalEvent('document','keydown',{key:'Escape'});assert.equal(h.visible(),false);assert.equal(h.document.activeElement.id,'sequence-stop');
});

test('UI DOUBLE V4: capture context distinguishes source draft from selected snapshot through edits and history',async()=>{
 const h=createHarness();await h.import(JSON.stringify(scene({name:'Source scene'})));await importSequence(h);await h.select('sequence-step-select','1');assert.match(h.get('capture-source').textContent,/Source scene/);assert.match(h.get('capture-source-state').textContent,/applied/i);assert.match(h.get('capture-replace-context').textContent,/Source scene/);assert.match(h.get('capture-replace-context').textContent,/Square/);await h.input('scene-name','Staged source');assert.match(h.get('capture-source').textContent,/Staged source/);assert.match(h.get('capture-source-state').textContent,/staged/i);assert.ok(h.get('capture-replace').getAttribute('aria-label').includes(h.get('capture-replace').textContent));assert.match(h.get('capture-replace').getAttribute('aria-label'),/Staged source/);assert.match(h.get('capture-replace').getAttribute('aria-label'),/Square/);await h.fire('discard','click');assert.ok(h.get('capture-replace').getAttribute('aria-label').includes(h.get('capture-replace').textContent));assert.match(h.get('capture-source').textContent,/Source scene/);assert.match(h.get('capture-source-state').textContent,/applied/i);await h.input('scene-name','Accepted source');await h.submit();assert.match(h.get('capture-source').textContent,/Accepted source/);await h.fire('undo','click');assert.match(h.get('capture-source').textContent,/Source scene/);await h.fire('redo','click');assert.match(h.get('capture-source').textContent,/Accepted source/);assert.match(h.get('capture-replace-context').textContent,/Square/);await h.input('scene-name','');assert.match(h.get('capture-source').textContent,/Unnamed draft/i);await h.input('scene-name','X'.repeat(100));assert.ok(h.get('capture-source').textContent.length<=80);assert.equal(h.visible(),false);
});

// v0.5 live edits are tested with Canvas command doubles, not actual pixels.
test('UI DOUBLE V5: explicit preview shows uncommitted draft and all six HSL inputs repaint synchronously',async()=>{
 const h=createHarness();await h.import(JSON.stringify(scene()));await h.input('object-hue',120);assert.equal(h.visible(),false);h.advance();await h.fire('show-scene','click');assert.equal(h.visible(),true);assert.equal(h.get('draft-label').textContent,'Live draft');
 for(const [id,value]of [['object-hue',260],['object-saturation',25],['object-lightness',45],['background-hue',40],['background-saturation',30],['background-lightness',15]]){clearDraws(h);await h.input(id,value);assert.equal(h.visible(),true,id);assert.ok(hasSceneDraw(h),id+' must repaint on input');assert.equal(h.get('undo').disabled,false,'only existing import history remains available');assert.equal(h.rafPending.size,0,'manual live edits do not schedule animated replay');}
 assert.ok(h.paint.some(p=>p.method==='fillRect'&&p.fillStyle==='hsl(40 30% 15%)'));assert.ok(h.paint.some(p=>p.strokeStyle==='hsl(260 25% 45%)'));assert.equal(h.get('draft-label').textContent,'Live draft');
});
test('UI DOUBLE V5: shape, geometry, selection, add, delete and presets repaint while live',async()=>{
 const h=createHarness();await h.import(JSON.stringify(scene()));h.advance();await h.fire('show-scene','click');
 for(const [id,value]of [['shape','square'],['position-x',60],['position-y',40],['size',20]]){clearDraws(h);await h.input(id,value);assert.equal(h.visible(),true);assert.ok(hasSceneDraw(h));}
 await h.select('add-shape','triangle');assert.equal(h.visible(),true);await h.fire('add-object','click');assert.equal(h.visible(),true);const added=h.get('object-select').value;assert.equal(h.get('object-count').textContent,'2 / 12');await h.select('object-select','object-1');assert.equal(h.visible(),true);await h.select('object-select',added);await h.fire('delete-object','click');assert.equal(h.visible(),true);assert.equal(h.get('object-count').textContent,'1 / 12');await h.select('preset','0');assert.equal(h.visible(),true);assert.equal(h.get('draft-label').textContent,'Live draft');
});
test('UI DOUBLE V5: invalid live draft clears immediately and correction never reactivates it',async()=>{
 const h=createHarness();await h.fire('show-scene','click');clearDraws(h);await h.input('position-x',0);assertOnlyBlackPaint(h);await h.input('position-x',50);assert.equal(h.visible(),false);h.advance(100000);h.runTimers();assert.equal(h.visible(),false);await h.fire('show-scene','click');assert.equal(h.visible(),true);
});
for(const action of ['hide','escape','blur','resize','pagehide','freeze','visibilitychange','reduced-motion'])test(`UI DOUBLE V5: ${action} revokes live preview; further valid edits stay hidden`,async()=>{
 const h=createHarness();await h.fire('show-scene','click');await h.input('object-hue',100);assert.equal(h.visible(),true);
 if(action==='hide')await h.fire('hide-scene','click');else if(action==='escape')await h.globalEvent('document','keydown',{key:'Escape'});else if(action==='visibilitychange'){h.document.hidden=true;await h.globalEvent('document','visibilitychange');h.document.hidden=false;}else if(action==='reduced-motion')await h.setReducedMotion(true);else await h.globalEvent(action==='freeze'?'document':'window',action);
 assert.equal(h.visible(),false);h.advance(100000);clearDraws(h);await h.input('object-hue',200);assertOnlyBlackPaint(h);h.runTimers();h.runFrame();assert.equal(h.visible(),false);
});
test('UI DOUBLE V5: live draft export remains blocked, discard restores accepted, Apply creates one history step',async()=>{
 const h=createHarness();await h.import(JSON.stringify(scene()));h.advance();await h.fire('show-scene','click');await h.input('object-hue',260);assert.equal(await h.exportScene(),null);await h.fire('discard','click');assert.equal(h.get('object-hue').value,'200');assert.deepEqual(await h.exportScene(),scene());h.advance();await h.fire('show-scene','click');for(let i=0;i<20;i++)await h.input('object-hue',i);await h.submit();assert.equal((await h.exportScene()).scene.objects[0].color.h,19);await h.fire('undo','click');assert.deepEqual(await h.exportScene(),scene());
});
test('UI DOUBLE V5: sequence playback edit cancels RAF, conceals, and leaves stored snapshots independent',async()=>{
 const h=createHarness();await startSequence(h);const stale=[...h.rafPending.values()][0];h.runFrame(3500);await h.input('object-hue',260);assert.equal(h.visible(),false);assert.equal(h.rafPending.size,0);clearDraws(h);stale(100000);assert.equal(h.paint.length,0);await h.input('object-hue',180);assert.equal(h.visible(),false);assert.deepEqual(await exportSequence(h),Q.sequence());
});
test('UI DOUBLE V5: opening and closing editor retains live input feedback but Hide still revokes it',async()=>{
 const h=createHarness();await h.fire('show-scene','click');await h.fire('editor-toggle','click');assert.equal(h.visible(),true);assert.equal(h.get('editor-panel').hidden,true);await h.fire('editor-toggle','click');assert.equal(h.visible(),true);assert.equal(h.get('editor-panel').hidden,false);await h.input('object-hue',200);assert.equal(h.visible(),true);await h.fire('hide-scene','click');await h.fire('editor-toggle','click');await h.fire('editor-toggle','click');await h.input('object-hue',300);assert.equal(h.visible(),false);
});
test('UI DOUBLE V5: placement description distinguishes visible draft from hidden placement',async()=>{
 const h=createHarness();await h.fire('place-object','click');assert.match(h.get('scene-canvas').getAttribute('aria-label'),/hidden/i);await h.fire('place-object','click');h.advance();await h.fire('show-scene','click');await h.fire('place-object','click');assert.equal(h.visible(),true);assert.match(h.get('scene-canvas').getAttribute('aria-label'),/live|visible/i);assert.doesNotMatch(h.get('scene-canvas').getAttribute('aria-label'),/scene is hidden/i);
});
